func pages(from start: URL) -> AsyncThrowingStream<[Item], Error> {
  AsyncThrowingStream { cont in Task {
    var url: URL? = start; do {
      while let u = url {
        let (data, _) = try await URLSession.shared.data(from: u)
        let p = try JSONDecoder().decode(Page.self, from: data)
        cont.yield(p.items)                     // Page = items + nextPageToken
        url = p.nextPageToken.map { withToken($0, start) }
      }
      cont.finish()                             // finished the collection
    } catch { cont.finish(throwing: error) }
  } }
}
